{
  "title": "Ubud Eats and Unexpected Twists",
  "summary": "A slow, food-filled day around Ubud with a proper feast, a market-style bite, and one surprise after dark.",
  "stops": [
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "A gentle start with vegan plates and good coffee, because the crew likes late mornings and I know a guy who swears by the smoothie bowls."
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "A quick lotus-pond temple visit to stretch the legs before the next bite, terima kasih (thank you) to whoever suggested a slower pace."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "A proper local warung stop for fragrant rice and crispy chicken, the kind of unplanned snack stop this crew would never expect."
    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "A little history between meals, because even a food day needs a story or two."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": "m2",
      "note": "The big splurge dinner stays, and the crew earns it after a day of grazing."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "A surprise nightcap by the beach, because the sun won’t wait and neither should the night owls."
    }
  ]
}
